'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var strided = require( '@stdlib/blas/ext/base/sfill' ).ndarray;


// MAIN //

/**
* Fills a single-precision floating-point ndarray with a specified value.
*
* @param {float32ndarray} x - input ndarray
* @param {number} alpha - fill value
* @returns {float32ndarray} input ndarray
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var array = require( '@stdlib/ndarray/array' );
*
* var x = array( new Float32Array( [ 1.0, 2.0, 3.0 ] ) );
*
* sfill( x, 5.0 );
*
* var xbuf = x.data;
* // returns <Float32Array>[ 5.0, 5.0, 5.0 ]
*/
function sfill( x, alpha ) {
	var N = numelDimension( x, 0 );
	var stride = getStride( x, 0 );
	var offset = getOffset( x );

	strided( N, alpha, getData( x ), stride, offset );
	return x;
}


// EXPORTS //

module.exports = sfill;
